from collections import deque, Counter

def comps(mask):
    H,W=len(mask),len(mask[0]); seen=set(); out=[]
    for r in range(H):
      for c in range(W):
        if mask[r][c] and (r,c) not in seen:
          q=[(r,c)];seen.add((r,c)); pts=[]
          while q:
            p=q.pop();pts.append(p)
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
              x,y=p[0]+dr,p[1]+dc
              if 0<=x<H and 0<=y<W and mask[x][y] and (x,y) not in seen:
                seen.add((x,y));q.append((x,y))
          out.append(pts)
    return out
