# exact cover all 8 target cells by given dimensions, unrotated. Recursively choose uncovered cell with fewest valid placement options.
from functools import lru_cache
H,W=25,10
# assign type dims counts
from collections import Counter
req=Counter(dims)
slots=[(r,c) for r in range(H) for c in range(W) if mask8[r][c]]
slotset=set(slots)
placements={d:[] for d in req}
for h,w in req:
 for r in range(H-h+1):
  for c in range(W-w+1):
   cells=frozenset((i,j) for i in range(r,r+h) for j in range(c,c+w))
   if cells<=slotset:
    placements[(h,w)].append((r,c,cells))
print('placement counts', {d:len(x) for d,x in placements.items()})
# pre-index placements that cover a cell, dimension
bycell={p:[] for p in slots}
for d,pls in placements.items():
 for r,c,cells in pls:
  for p in cells: bycell[p].append((d,r,c,cells))

# Search; use tuple of unoccupied set and counts, but huge. use bit masks and canonical pieces.
index={p:i for i,p in enumerate(slots)}
plbits={d:[(r,c,sum(1<<index[p] for p in cells)) for r,c,cells in pls] for d,pls in placements.items()}
cellpl={i:[] for i in range(len(slots))}
for d,pls in plbits.items():
 for item in pls:
  r,c,b=item
  for i in range(len(slots)):
   if b>>i&1: cellpl[i].append((d,r,c,b))

calls=0; sols=[]
# choose most constrained uncovered cell including remaining piece count. Since coverage all cells and only rectangles.
def search(covered, counts, chosen, limit=10000):
 global calls
 calls+=1
 if len(sols)>=limit:return
 if all(v==0 for v in counts.values()):
  if covered==(1<<len(slots))-1: sols.append(chosen.copy())
  return
 # identify uncovered cell with fewest feasible placements
 best=None; candbest=None
 for i in range(len(slots)):
  if (covered>>i)&1: continue
  cands=[]
  for d,r,c,b in cellpl[i]:
   if counts.get(d,0)>0 and (covered & b)==0:
    # ensure placement does not overlap occupied; feasible
    cands.append((d,r,c,b))
  if not cands:return
  if candbest is None or len(cands)<len(candbest): best=i;candbest=cands
  if len(candbest)==1:break
 for d,r,c,b in candbest:
  counts[d]-=1
  search(covered|b,counts,chosen+[(d,r,c)],limit)
  counts[d]+=1
  if len(sols)>=limit:return
